    80→    public void RegisterValidator(TxType type, ITxValidator validator) => _validators[(byte)type] = validator;
    81→
    82→    /// <remarks>
    83→    /// Full and correct validation is only possible in the context of a specific block
    84→    /// as we cannot generalize correctness of the transaction without knowing the EIPs implemented
    85→    /// and the world state(account nonce in particular).
    86→    /// Even without protocol change, the tx can become invalid if another tx
    87→    /// from the same account with the same nonce got included on the chain.
    88→    /// As such, we can decide whether tx is well formed as long as we also validate nonce
    89→    /// just before the execution of the block / tx.
    90→    /// </remarks>
    91→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
    92→        _validators.TryGetByTxType(transaction.Type, out ITxValidator validator)
    93→            ? validator.IsWellFormed(transaction, releaseSpec)
    94→            : TxErrorMessages.InvalidTxType(releaseSpec.Name);
    95→}
    96→
    97→public class CompositeTxValidator(params ITxValidator[] validators) : ITxValidator
    98→{
    99→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   100→    {
   101→        foreach (ITxValidator validator in validators)
   102→        {
   103→            ValidationResult isWellFormed = validator.IsWellFormed(transaction, releaseSpec);
   104→            if (!isWellFormed)
   105→            {
   106→                return isWellFormed;
   107→            }
   108→        }
   109→
   110→        return ValidationResult.Success;
   111→    }
   112→}
   113→
   114→public sealed class IntrinsicGasTxValidator : ITxValidator
   115→{
   116→    public static readonly IntrinsicGasTxValidator Instance = new();
   117→    private IntrinsicGasTxValidator() { }
   118→
   119→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   120→    {
   121→        // This is unnecessarily calculated twice - at validation and execution times.
   122→        IntrinsicGas intrinsicGas = IntrinsicGasCalculator.Calculate(transaction, releaseSpec);
   123→        return transaction.GasLimit < intrinsicGas.MinimalGas
   124→            ? TxErrorMessages.IntrinsicGasTooLow
   125→            : ValidationResult.Success;
   126→    }
   127→}
   128→
   129→public sealed class ReleaseSpecTxValidator(Func<IReleaseSpec, bool> validate) : ITxValidator
   130→{
   131→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   132→        !validate(releaseSpec) ? TxErrorMessages.InvalidTxType(releaseSpec.Name) : ValidationResult.Success;
   133→}
   134→
   135→public sealed class ExpectedChainIdTxValidator(ulong chainId) : ITxValidator
   136→{
   137→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   138→        transaction.ChainId != chainId ? TxErrorMessages.InvalidTxChainId(chainId, transaction.ChainId) : ValidationResult.Success;
   139→}
